insert into recommendations
  (id, name, destination, tag, category, price_band, duration_minutes, lat, lng, interests, window_start, window_end, vibe, description, why_it_fits, evidence_source, verified, priority)
values
  ('pune-dagdusheth', 'Dagdusheth Halwai Ganpati Temple', 'Pune', 'tourist_essential', 'temple', 'free', 45, 18.51643, 73.85611, ARRAY['spiritual', 'local_life']::text[], '06:30', '08:00', 'Bright, loud, genuinely moving', 'Go at dawn, when it''s mostly people on their way to work rather than people on their way to a photo.', '{"spiritual":"It''s the one temple in Pune that locals and visitors both actually mean when they say ''the temple''.","local_life":"Morning darshan here is a daily routine for half the old city, not a tourist ritual."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-shaniwar-wada', 'Shaniwar Wada', 'Pune', 'tourist_essential', 'sight', 'low', 75, 18.51938, 73.85536, ARRAY['history', 'architecture', 'photography']::text[], '09:00', '10:30', 'Open, sunbaked, more ruin than palace', 'The Peshwa seat of power, burnt down and left as foundations — go for the scale and the gate, not for furnished rooms.', '{"history":"You can''t really read Pune''s Maratha history without standing in this courtyard first.","architecture":"The Delhi Gate alone is worth the ticket — the rest is foundations and imagination.","photography":"Best in low morning light, before the courtyard turns into a glare trap."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-aga-khan', 'Aga Khan Palace', 'Pune', 'tourist_essential', 'sight', 'low', 90, 18.55233, 73.90148, ARRAY['history', 'nature', 'architecture']::text[], '10:45', '12:15', 'Quiet lawns, heavy history', 'Gandhi, Kasturba and Mahadev Desai were interned here. The memorials in the garden land harder than the building does.', '{"history":"It''s the rare freedom-movement site that still feels like a house someone lived in.","nature":"The lawns are the calmest green space you''ll find this close to the centre.","architecture":"Italianate arches and deep verandahs, built as famine relief work."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-kelkar-museum', 'Raja Dinkar Kelkar Museum', 'Pune', 'tourist_essential', 'museum', 'low', 90, 18.51077, 73.85444, ARRAY['history', 'local_life']::text[], '11:00', '12:30', 'Dense, cluttered, quietly obsessive', 'One man''s lifetime of collecting ordinary Indian objects — lamps, nutcrackers, door frames. Far better than it sounds.', '{"history":"History told through what people actually used at home, not through kings and dates.","local_life":"The everyday-object collection explains more about how India lived than any fort will."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-sinhagad', 'Sinhagad Fort', 'Pune', 'tourist_essential', 'outdoors', 'low', 240, 18.36472, 73.75751, ARRAY['nature', 'history', 'photography']::text[], '06:00', '10:00', 'Cold wind, steep climb, enormous view', 'An hour out of the city and a real climb. Weekend mornings are crowded with Pune''s own trekkers — that''s part of the appeal.', '{"nature":"The best big-landscape morning available within reach of the city.","history":"Tanaji''s fort — the one piece of Maratha history Punekars will bring up unprompted.","photography":"Get above the cloud line early and the whole Sahyadri ridge opens up."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-vaishali', 'Vaishali, FC Road', 'Pune', 'local_favourite', 'food', 'mid', 60, null, null, ARRAY['food', 'cafes', 'local_life']::text[], '08:00', '09:30', 'Formica tables, unhurried, institution-grade', 'Sambar, filter coffee and decades of students arguing at the same tables. Expect to wait; it''s worth waiting.', '{"food":"This is the breakfast a Punekar would take you to before anything else opens.","cafes":"The filter coffee is the point, and nobody will rush you out of the chair.","local_life":"More of Pune''s actual social life has happened here than at any monument in the city."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-bedekar', 'Bedekar Tea Stall', 'Pune', 'local_favourite', 'food', 'low', 30, 18.51481, 73.84994, ARRAY['food']::text[], '08:30', '10:00', 'Tiny, brisk, deadly serious about misal', 'Pune misal at its sharpest. Order the kat separately if you want to survive it, and don''t linger — nobody does. Closed Mondays.', '{"food":"If you eat one thing in Pune that you can''t get properly anywhere else, make it this."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-parvati', 'Parvati Hill', 'Pune', 'local_favourite', 'outdoors', 'free', 90, 18.49757, 73.84707, ARRAY['spiritual', 'nature', 'photography']::text[], '06:00', '07:30', 'Stone steps, morning walkers, whole-city view', 'A flight of steps up to an old temple complex, climbed daily by half the neighbourhood. Go before the sun is properly up.', '{"spiritual":"A working temple people climb to out of habit, not a monument they visit.","nature":"The clearest view of Pune you can get without leaving the city.","photography":"The city wakes up underneath you — worth the early alarm."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-pataleshwar', 'Pataleshwar Cave Temple', 'Pune', 'local_favourite', 'temple', 'free', 45, 18.52695, 73.84985, ARRAY['spiritual', 'history', 'architecture']::text[], '08:30', '10:00', 'Dark, cool, startlingly old', 'An 8th-century temple cut straight out of basalt, sitting in the middle of a busy road. Most people drive past it daily.', '{"spiritual":"Still an active shrine, and almost always empty enough to sit in.","history":"Rock-cut, centuries older than anything Peshwa-era in this city.","architecture":"Carved downward out of one piece of rock — no joints, no masonry."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-vetal-tekdi', 'Vetal Tekdi', 'Pune', 'local_favourite', 'outdoors', 'free', 105, 18.52556, 73.81534, ARRAY['nature', 'local_life', 'photography']::text[], '06:00', '07:45', 'Dust, birdsong, regulars who all know each other', 'The city''s own hill. No ticket, no gate — just paths worn in by people who walk them every single morning.', '{"nature":"The closest thing to wilderness inside Pune''s limits.","local_life":"Walking here at 6am is the single most Pune thing you can do.","photography":"Good light and good birds, both before seven."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-tulshibaug', 'Tulshibaug Market', 'Pune', 'local_favourite', 'market', 'free', 90, 18.51344, 73.85557, ARRAY['markets', 'local_life']::text[], '17:00', '19:00', 'Narrow, crowded, relentlessly practical', 'Lanes of household goods, bangles and steel vessels behind an old temple. Come to watch the bargaining, not to buy.', '{"markets":"Everything is negotiable and nothing is aimed at you.","local_life":"This is where the city shops for itself, not for visitors."}'::jsonb, 'seeded_anchor', false, 6),
  ('pune-chitale', 'Chitale Bandhu Mithaiwale', 'Pune', 'local_favourite', 'food', 'low', 30, null, null, ARRAY['food']::text[], '16:30', '17:30', 'Queue, counter, no seating, no nonsense', 'Bakarwadi to take home. The shop famously used to shut in the afternoon and the city simply worked around it.', '{"food":"The thing Punekars actually carry with them when they travel."}'::jsonb, 'seeded_anchor', false, 7),
  ('pune-shinde-chhatri', 'Shinde Chhatri, Wanowrie', 'Pune', 'hidden_gem', 'sight', 'low', 75, 18.49163, 73.89727, ARRAY['history', 'architecture', 'photography', 'spiritual']::text[], '15:00', '16:30', 'Ornate, empty, oddly solemn', 'A memorial to Mahadji Shinde with carving far more elaborate than anything at the famous sites — and usually nobody in it.', '{"history":"The best stonework in Pune is in a memorial most visitors never hear about.","architecture":"Anglo-Rajasthani carving at a level the famous sites simply don''t reach.","photography":"Empty enough that you can actually compose a shot without waiting.","spiritual":"Quiet enough to sit in for an hour without anyone hurrying you along."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-kasba-peth', 'Kasba Peth lanes & Kasba Ganpati', 'Pune', 'hidden_gem', 'sight', 'free', 105, 18.51903, 73.85724, ARRAY['local_life', 'history', 'spiritual', 'architecture', 'photography']::text[], '09:00', '10:45', 'Old wooden facades, tight lanes, lived-in', 'The oldest part of the city, and the home of Pune''s presiding Ganpati. Walk it slowly; there is nothing to ''see'' and everything to notice.', '{"local_life":"The one walk that shows you what Pune was before it became a metro.","history":"Older than the Peshwas, and still entirely residential.","spiritual":"Kasba Ganpati is the city''s gram daivat — first honours in the festival, every year.","architecture":"Carved wooden wada facades, still lived in rather than restored.","photography":"Lanes narrow enough that the light does the work for you."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-taljai', 'Taljai Tekdi', 'Pune', 'hidden_gem', 'outdoors', 'free', 90, 18.47582, 73.8424, ARRAY['nature', 'photography']::text[], '06:30', '08:00', 'Wooded, quiet, thinner crowd than Vetal', 'The hill people go to when Vetal Tekdi feels busy. Denser tree cover, more birds, fewer conversations.', '{"nature":"Genuinely peaceful, and almost never mentioned to visitors.","photography":"Thick enough cover that you forget you''re inside a city."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-marz-o-rin', 'Marz-O-Rin, MG Road', 'Pune', 'hidden_gem', 'cafe', 'low', 75, 18.51651, 73.87909, ARRAY['food', 'cafes', 'local_life']::text[], '13:00', '14:30', 'Faded Irani cafe, soft light, slow', 'Sandwiches, cold coffee and an interior that hasn''t been updated in decades — deliberately. An afternoon holdout from an older Pune.', '{"food":"Not a destination dish, just a place worth an unhurried hour.","cafes":"The last kind of café that expects you to stay a while.","local_life":"One of the last Irani-cafe afternoons left in the city."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-pu-la-garden', 'Pu La Deshpande Garden', 'Pune', 'hidden_gem', 'outdoors', 'low', 90, 18.49108, 73.83815, ARRAY['nature', 'photography']::text[], '08:00', '09:30', 'Japanese-garden calm, water, raked stone', 'A Japanese-style garden modelled on one in Okayama, sitting incongruously beside a Pune canal. Go early, before the school groups.', '{"nature":"Manicured quiet — the opposite of the hills, and a good counterweight to them.","photography":"Composed on purpose, so almost every angle already works."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-khunya-murlidhar', 'Khunya Murlidhar Temple', 'Pune', 'hidden_gem', 'temple', 'free', 45, 18.51159, 73.85056, ARRAY['spiritual', 'history']::text[], '07:00', '08:30', 'Small, old, tucked behind the noise', 'A peth temple with a grim name and a long story behind it, wedged into a lane most visitors never turn down.', '{"spiritual":"Small enough that you''ll likely have it to yourself.","history":"The kind of place where the story matters more than the building."}'::jsonb, 'seeded_anchor', false, 6),
  ('pune-laxmi-road', 'Laxmi Road at dusk', 'Pune', 'hidden_gem', 'market', 'free', 90, 18.51535, 73.86877, ARRAY['markets', 'local_life', 'photography']::text[], '18:00', '19:30', 'Shoulder-to-shoulder, lit up, chaotic', 'Not a sight — a street. Walk its length in the evening and you''ll understand the city''s density better than any museum will explain it.', '{"markets":"Every kind of shop, none of them aimed at visitors.","local_life":"An hour here beats a day of monuments for actually feeling the place.","photography":"Shop lights come on around seven and the whole street changes character."}'::jsonb, 'seeded_anchor', false, 7)
